    std::env::var("IIAC_PERF_BIN").unwrap_or_else(|_| env!("CARGO_BIN_EXE_iiac-perf").to_string())
}

#[test]
#[ignore = "machine-specific: run alone on a quiet box that shows the relaxation (see module doc)"]
